$h="example.com";$tcp=[Net.Sockets.TcpClient]::new($h,443);$ssl=[Net.Security.SslStream]::new($tcp.GetStream(),$false,({$true}));try{$ssl.AuthenticateAsClient($h);$c=[Security.Cryptography.X509Certificates.X509Certificate2]::new($ssl.RemoteCertificate);$ch=[Security.Cryptography.X509Certificates.X509Chain]::new();[void]$ch.Build($c);$ch.ChainElements|%{$_.Certificate|Select Subject,Issuer,Thumbprint}}finally{$ssl.Dispose();$tcp.Dispose()}
